sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // FLEET-34: FLEET - Validate Check-out (reservation_state changes to ACTIVE)
    var errors = [];
    var vehicleId = current.getValue('assigned_vehicle');

    // (a) passing CHECK_OUT inspection for this reservation and its current vehicle
    var ins = new GlideRecord('x_1850693_enterp_0_inspection');
    ins.addQuery('reservation', current.getUniqueValue());
    ins.addQuery('vehicle', vehicleId);
    ins.addQuery('inspection_type', 'CHECK_OUT');
    ins.addQuery('overall_pass', true);
    ins.setLimit(1);
    ins.query();
    if (!vehicleId || !ins.hasNext()) {
        errors.push('A passing check-out inspection of the assigned vehicle is required before check-out.');
    }

    // (b) license of the assigned driver valid through the end of the trip (D-20)
    var driver = current.getValue('assigned_driver') || current.getValue('requested_by');
    if (!FleetLicenseUtils.isValidOn(driver, new GlideDateTime(current.getValue('end_datetime')))) {
        errors.push("The assigned driver's license is missing or expires before the trip ends.");
    }

    // (c) check-out odometer not below the vehicle odometer
    if (vehicleId && !current.check_out_odometer.nil() &&
        parseInt(current.getValue('check_out_odometer'), 10) < parseInt(current.assigned_vehicle.current_odometer, 10)) {
        errors.push('Check-out odometer cannot be lower than the vehicle odometer (' + current.assigned_vehicle.current_odometer + ').');
    }

    // (d) not earlier than start minus 1 hour
    var earliest = new GlideDateTime(current.getValue('start_datetime'));
    earliest.addSeconds(-3600);
    if (new GlideDateTime().compareTo(earliest) < 0) {
        errors.push('Check-out is allowed from 1 hour before the start time (' + earliest.getDisplayValue() + ').');
    }

    if (errors.length) {
        for (var i = 0; i < errors.length; i++) {
            gs.addErrorMessage(errors[i]);
        }
        current.setAbortAction(true);
    }
})(current, previous);
